def safe_repr(obj, clip=None):
    try:
        s = repr(obj)
        if not clip or len(s) <= clip:
            return s
        return s[:clip - 4] + b'..' + s[-2:]
    except:
        return b'N/A'

    return


def trunc(obj, max, left=0):
    s = str(obj)
    s = s.replace(b'\n', b'|')
    if len(s) > max:
        if left:
            return b'...' + s[len(s) - max + 3:]
        else:
            return s[:max - 3] + b'...'

    else:
        return s
    return


def pp(i, base=1024):
    degree = 0
    pattern = b'%4d     %s'
    while i > base:
        pattern = b'%7.2f %s'
        i = i / float(base)
        degree += 1

    scales = [
     5, 6, 7, 8, 9, 10]
    return pattern % (i, scales[degree])


def pp_timestamp(t):
    if t is None:
        return b''
    else:
        h, m, s = int(t / 3600), int(t / 60 % 60), t % 60
        return b'%02d:%02d:%05.2f' % (h, m, s)
